<span class="line">            <span class="token class-name">ApiError</span><span class="token punctuation">::</span><span class="token class-name">NotFound</span><span class="token punctuation">(</span>id<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span></span>
